import struct


class ClientHelloMaker:
    """Generate a valid TLS 1.3 ClientHello with a fake SNI."""
    tls_ch_template = bytes.fromhex(
        ""
    )
    static1 = tls_ch_template[:11]  # fixed header
    static2 = b"\x20"
    static3 = tls_ch_template[76:120]
    static4 = tls_ch_template[127 + 13:262 + 13]  # after SNI placeholder
    static5 = b"\x00\x15"

    @classmethod
    def get_client_hello_with(cls, rnd: bytes, sess_id: bytes, target_sni: bytes, key_share: bytes) -> bytes:
        """Build a full ClientHello (517 bytes)."""
        server_name_ext = (
                struct.pack("!H", len(target_sni) + 5) +
                struct.pack("!H", len(target_sni) + 3) +
                b"\x00" +
                struct.pack("!H", len(target_sni)) +
                target_sni
        )
        padding_ext = struct.pack("!H", 219 - len(target_sni)) + (b"\x00" * (219 - len(target_sni)))
        return cls.static1 + rnd + cls.static2 + sess_id + cls.static3 + server_name_ext + cls.static4 + key_share + cls.static5 + padding_ext
